const item = $input.first()?.json || {};
const allowedJobTypes = ['SCOUT', 'RESEARCH', 'QUALIFY', 'BUILD', 'VALIDATE'];
const rawType = String(item.job_type || 'SCOUT').trim().toUpperCase();

if (!allowedJobTypes.includes(rawType)) {
  throw new Error('Disallowed job_type: ' + rawType + '. Must be one of: ' + allowedJobTypes.join(', '));
}

const execId = String($execution.id || 'manual');
const jobId = item.job_id ? String(item.job_id).trim() : 'n8n-' + rawType.toLowerCase() + '-' + execId;
const dryRun = item.dry_run !== undefined ? Boolean(item.dry_run) : true;
const priority = String(item.priority || 'NORMAL').toUpperCase();
const inputData = item.input && typeof item.input === 'object' ? item.input : { mode: 'fixture_only' };

return [{
  json: {
    job_type: rawType,
    job_id: jobId,
    dry_run: dryRun,
    priority: priority,
    input: inputData,
    run: true
  }
}];

const healthData = $input.first()?.json || {};
const isHeld = Boolean(healthData.health?.automation_held || healthData.attention?.automation_held);
const apiStatus = healthData.api_status;

if (apiStatus !== 'OK') {
  throw new Error('API health check failed or API unreachable: status=' + apiStatus);
}

if (isHeld) {
  throw new Error('Global automation is currently HELD. Job execution blocked by operator hold.');
}

const req = $('Validate Input & Build Request').first().json;
return [{ json: req }];

const res = $input.first()?.json || {};
const status = res.status || 'UNKNOWN';
const jobId = res.job_id || 'unknown';
const jobType = res.job_type || 'unknown';
const recoverable = Boolean(res.recoverable);
const errorCode = res.error_code || null;
const nextAction = res.next_action || null;

const isSuccess = status === 'COMPLETED';

return [{
  json: {
    success: isSuccess,
    job_id: jobId,
    job_type: jobType,
    status: status,
    error_code: errorCode,
    recoverable: recoverable,
    next_action: nextAction,
    summary: isSuccess
      ? '✅ Job ' + jobId + ' (' + jobType + ') completed successfully.'
      : '⚠️ Job ' + jobId + ' (' + jobType + ') ended with status ' + status + '. Code: ' + (errorCode || 'NONE') + '. Action: ' + (nextAction || 'Review execution history.')
  }
}];
